163→    fn build_install_context(&self) -> InstallContext {
164→        let detected_managers = self
165→            .probe
166→            .inactive_managers()
167→            .iter()
168→            .map(|m| m.name.clone())
169→            .collect::<Vec<_>>();
170→        InstallContext {
171→            detected_managers,
172→            platform: Platform::current(),
173→        }
174→    }
