176→    /// Check whether the network is reachable.
177→    ///
178→    /// Attempts a TCP connection to a well-known host with a 2-second timeout.
179→    /// Returns `true` if the connection succeeds, `false` otherwise.
180→    pub fn check_network(&self) -> bool {
181→        // Try multiple well-known hosts to reduce false negatives
182→        const TARGETS: &[(&str, u16)] = &[
183→            ("1.1.1.1", 443), // Cloudflare DNS
184→            ("8.8.8.8", 443), // Google DNS
185→            ("9.9.9.9", 443), // Quad9 DNS
186→        ];
187→        let timeout = Duration::from_secs(2);
188→
189→        for &(host, port) in TARGETS {
190→            let addr = format!("{}:{}", host, port);
191→            if let Ok(addr) = addr.parse() {
192→                if TcpStream::connect_timeout(&addr, timeout).is_ok() {
193→                    return true;
194→                }
195→            }
196→        }
197→        false
198→    }
